N = int(input())
heights = [int(n) for n in input().split()]
max_h = max(heights)
interval = [1, max_h]

def get_final_energy(e, heights):
	for h in heights:
		e = 2 * e - h
	return e
while interval[0] < interval[1] - 1:
	mid = (interval[0] + interval[1]) // 2
	fe = get_final_energy(mid, heights)
	if fe >= 0:
		interval[1] = mid
	else:
		interval[0] = mid
if get_final_energy(interval[0], heights) >= 0:
	print(interval[0])
else:
	print(interval[1])
